                    ((((Val::from("to ") + ctx.var("@wrpd$").get_at(runtime::index(&l_j.clone())?)?) + Val::from(" is "))
                        + ctx.var("@wrpp").get_at(runtime::index(&l_j.clone())?)?)
                        + Val::from(" zeny."))
