#[derive(Clone, Copy, Debug)]
enum FSetkafcodeStep {
    Start,
    SSET,
}

fn f_setkafcode_run(ctx: &Ctx, mut step: FSetkafcodeStep, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_code = Val::from(0);
    let mut l_comp_name_s = Val::from("");
    let mut l_npc_name_s = Val::from("");
    'machine: loop {
        match step {
            FSetkafcodeStep::Start => {
                l_npc_name_s = runtime::arg(&args, 0, Val::from(0));
                l_comp_name_s = runtime::arg(&args, 1, Val::from(0));
                ctx.lines(args![l_npc_name_s.clone()])?;
                if ctx.var("#kafra_code").get()? == 0 {
                    ctx.lines(args![
                        ((Val::from("") + l_comp_name_s.clone()) + Val::from(" proudly presents you a new service:")),
                        "Additional storage protection with a password."
                    ])?;
                    ctx.next()?;
                    if Val::from(runtime::select_values(
                        ctx,
                        &[Val::from("Set new password -> 5000z"), Val::from("Cancel")],
                    )?) == 1
                    {
                        f_setkafcode_run(ctx, FSetkafcodeStep::SSET, vec![l_npc_name_s.clone(), l_comp_name_s.clone()])?;
                    }
                    ctx.close_window()?;
                    ctx.call(Function::Cutin, vec![Val::from(""), Val::from(255)])?;
                    return Err(Stop::End);
                }
                ctx.mes("Your storage is protected with a password. What would you do now?")?;
                ctx.next()?;
                'b1: {
                    let subject1 = Val::from(runtime::select_values(
                        ctx,
                        &[
                            Val::from("Change old password -> 5000z"),
                            Val::from("Remove storage password -> 1000z"),
                            Val::from("Cancel"),
                        ],
                    )?);
                    let mut matched1 = false;
                    let no_case1 = !subject1.loosely_equals(&Val::from(1))
                        && !subject1.loosely_equals(&Val::from(2))
                        && !subject1.loosely_equals(&Val::from(3));
                    if !matched1 && subject1.loosely_equals(&Val::from(1)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.lines(args![
                            l_npc_name_s.clone(),
                            "At first, please enter your ^0000FFold password^000000."
                        ])?;
                        l_code = crate::kafras_functions_kafras::f_entkafcode(ctx, vec![])?;
                        if (!(l_code.clone().is_true()) || !l_code.clone().loosely_equals(&ctx.var("#kafra_code").get()?)) {
                            ctx.mes("Wrong password. You can't set a new password.")?;
                            ctx.call(Function::Emotion, vec![ctx.constant("ET_SCRATCH")?])?;
                            break 'b1;
                        }
                        ctx.next()?;
                        f_setkafcode_run(ctx, FSetkafcodeStep::SSET, vec![l_npc_name_s.clone(), l_comp_name_s.clone()])?;
                        break 'b1;
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(2)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.lines(args![l_npc_name_s.clone(), "Please, enter your password before its removal."])?;
                        l_code = crate::kafras_functions_kafras::f_entkafcode(ctx, vec![])?;
                        if !(l_code.clone().is_true()) {
                            ctx.mes("The password hasn't been removed.")?;
                            ctx.call(Function::Emotion, vec![ctx.constant("ET_SCRATCH")?])?;
                            break 'b1;
                        }
                        ctx.next()?;
                        ctx.lines(args![l_npc_name_s.clone()])?;
                        if ctx.var("Zeny").get()?.number()? < 1000 {
                            ctx.mes("You don't have enough zeny.")?;
                            ctx.call(Function::Emotion, vec![ctx.constant("ET_MONEY")?])?;
                            break 'b1;
                        }
                        ctx.var("Zeny").set((ctx.var("Zeny").get()?.try_sub(Val::from(1000))?))?;
                        if l_code.clone().loosely_equals(&ctx.var("#kafra_code").get()?) {
                            ctx.var("#kafra_code").set(Val::from(0))?;
                            ctx.lines(args![
                                "You've successfully cleared your storage password.",
                                ((Val::from("Thank you for using ") + l_comp_name_s.clone()) + Val::from("."))
                            ])?;
                            ctx.call(Function::Emotion, vec![ctx.constant("ET_THANKS")?])?;
                        } else {
                            ctx.lines(args![
                                "Wrong password. We won't return your 1000z.",
                                "Please, next time enter correct password."
                            ])?;
                            ctx.call(Function::Emotion, vec![ctx.constant("ET_SORRY")?])?;
                        }
                        break 'b1;
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(3)) {
                        matched1 = true;
                    }
                    if matched1 {
                        break 'b1;
                    }
                }
                ctx.close_window()?;
                ctx.call(Function::Cutin, vec![Val::from(""), Val::from(255)])?;
                return Err(Stop::End);
            }
            FSetkafcodeStep::SSET => {
                l_npc_name_s = runtime::arg(&args, 0, Val::from(0));
                l_comp_name_s = runtime::arg(&args, 1, Val::from(0));
                ctx.lines(args![
                    l_npc_name_s.clone(),
                    "Now enter your ^FF0000new password^000000 to protect your storage from thieves."
                ])?;
                l_code = crate::kafras_functions_kafras::f_entkafcode(ctx, vec![])?;
                if !(l_code.clone().is_true()) {
                    ctx.mes("The password hasn't been changed.")?;
                    ctx.call(Function::Emotion, vec![ctx.constant("ET_SCRATCH")?])?;
                    return Ok(Val::from(0));
                }
                ctx.next()?;
                ctx.lines(args![l_npc_name_s.clone()])?;
                if ctx.var("Zeny").get()?.number()? < 5000 {
                    ctx.mes("You don't have enough zeny.")?;
                    ctx.call(Function::Emotion, vec![ctx.constant("ET_MONEY")?])?;
                    return Ok(Val::from(0));
                }
                ctx.var("Zeny").set((ctx.var("Zeny").get()?.try_sub(Val::from(5000))?))?;
                ctx.var("#kafra_code").set(l_code.clone())?;
                ctx.lines(args![
                    "You've protected your storage with a secret password.",
                    ((Val::from("Thank you for using ") + l_comp_name_s.clone()) + Val::from("."))
                ])?;
                ctx.call(Function::Emotion, vec![ctx.constant("ET_THANKS")?])?;
                return Ok(Val::from(0));
            }
        }
    }
}

pub fn f_setkafcode(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    f_setkafcode_run(ctx, FSetkafcodeStep::Start, args)
}
